SELECT 'gongkao', '售价求成本', 'kp-pf-cpr-price-to-cost', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "售价求成本"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心推论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "把 1 + 利润率 作为分母，除过去！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“商品售价 120 元，利润率 20%，求成本？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{成本} = \\frac{\\text{售价}}{1 + \\text{利润率}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "成本 ≠ 售价 × (1 - 利润率)！", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多人想当然地用 120 × (1 - 20%) = 96 去求成本。大错特错！利润率的基准永远是【成本】，不是售价！正确的成本是 120 ÷ 1.2 = 100。"}]}]}]}$$ AS jsonb), NULL, '售价求成本的核心考点与实战推导。', category_node.id, CAST('["数量关系", "经济利润", "售价求成本"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pf_cpr_price_to_cost", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
